/* Кабинет жителя и кабинет предпринимателя */
const ME = 'Кабинет жителя';
const BZ = 'Кабинет предпринимателя';
const RES = ['resident'];
route('/me', { title: 'Кабинет: обзор', area: 'me', need: RES, group: ME, render: () => pageHead('Добрый день!', { kicker: 'Личный кабинет', actions: btn('Разместить', { href: '#/submit', cls: 'btn-primary', icon: 'plus' }) }) + `<div class="tiles">
<a class="tile kpi" href="#/me/messages" style="text-decoration:none"><span>Новые сообщения</span><b>2</b><span>Анна (пример): «Да, ещё актуально»</span></a>
<a class="tile kpi" href="#/me/notifications" style="text-decoration:none"><span>Уведомления</span><b>2</b><span>Объявление опубликовано</span></a>
<a class="tile kpi" href="#/me/pubs" style="text-decoration:none"><span>Мои публикации</span><b>4</b><span>1 на проверке · 1 отклонено</span></a>
<section class="tile w8"><div class="tile-h"><h2>Требует внимания</h2></div><div class="mini"><div class="r"><span>${badge('Отклонено', 'err')} «Продам гараж» — не указана цена и фото</span>${btn('Исправить', { href: '#/submit/ad?edit=1', cls: 'btn-sm btn-secondary' })}</div><div class="r"><span>${badge('Срок истёк')} «Найдена кошка»</span>${btn('Продлить', { cls: 'btn-sm btn-secondary', attrs: demo('Демо: продлено на 30 дней') })}</div></div></section>
<section class="tile"><div class="tile-h"><h2>Обращение № 42</h2>${badge('В работе', 'warn')}</div><p class="meta">Не горит фонарь на улице · обновлено вчера</p>${btn('Открыть', { href: '#/me/issues', cls: 'btn-sm btn-secondary' })}</section>
<section class="tile w6"><div class="tile-h"><h2>Рекомендации</h2><a class="more" href="#/me/reco">Все${ic('arrow', 'i-s')}</a></div><div class="mini">${DATA.events.slice(0, 2).map((e) => `<a href="#/events/${e.id}"><span>${e.title}</span><span class="meta">${e.d} · ${e.w}</span></a>`).join('')}</div></section>
<section class="tile w6"><div class="tile-h"><h2>Мои группы</h2><a class="more" href="#/me/groups">Все${ic('arrow', 'i-s')}</a></div><div class="mini">${DATA.groups.slice(0, 2).map((g) => `<a href="#/groups/${g.id}"><span>${g.name}</span><span class="meta">${g.members}</span></a>`).join('')}</div></section></div>` });
route('/me/pubs', { title: 'Мои публикации', area: 'me', need: RES, group: ME, render: () => pageHead('Мои публикации', { actions: btn('Новое объявление', { href: '#/submit/ad', cls: 'btn-primary', icon: 'plus' }) }) + tabs('pubs', [['all', 'Все'], ['live', 'Опубликованы'], ['rev', 'На проверке'], ['rej', 'Отклонены']], 'all') +
  st(() => `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Публикация</th><th>Тип</th><th>Статус</th><th>Примечание</th><th></th></tr></thead><tbody>${DATA.myPubs.map((x) => `<tr><td><b>${x.title}</b></td><td data-l="Тип">${x.kind}</td><td data-l="Статус">${badge(x.status, x.tone)}</td><td data-l="Примечание" class="meta">${x.note}</td><td class="tact">${btn('Изменить', { href: '#/submit/ad?edit=1', cls: 'btn-sm btn-ghost' })}${btn('Снять', { cls: 'btn-sm btn-ghost', attrs: 'data-act="modal" data-id="danger" data-title="Снять публикацию?" data-text="Объявление пропадёт из поиска. Вернуть можно в течение 30 дней." data-word="СНЯТЬ" data-btn="Снять" data-ok="Демо: снято с публикации"' })}</td></tr>`).join('')}</tbody></table></div>`, ['У вас пока нет публикаций', 'Разместите первое объявление — это бесплатно.', btn('Подать объявление', { href: '#/submit/ad', cls: 'btn-primary' })]) });
route('/me/issues', { title: 'Мои обращения', area: 'me', need: RES, group: ME, render: () => pageHead('Мои обращения', { sub: 'Обращения видят только сотрудники SVETLY. В администрацию автоматически не передаются.', actions: btn('Новое обращение', { href: '#/submit/issue', cls: 'btn-primary', icon: 'plus' }) }) + st(() => `<div class="lst">${DATA.issues.map((i) => `<article class="card"><div class="status-row">${badge(i.status, i.tone)}<span class="meta">№ ${i.id} · ${i.ago}</span></div><h3 style="margin:8px 0">${i.title}</h3><ol class="steps" style="display:flex;gap:16px;flex-wrap:wrap">${['Принято', 'В работе', 'Решено'].map((s, k) => `<li class="${k < i.step ? 'on' : k === i.step ? 'now' : ''}"><span class="dot"></span>${s}</li>`).join('')}</ol>${i.step === 1 ? '<p class="meta">Ответ сотрудника (пример): «Передали электрику, ориентировочно на этой неделе».</p>' : ''}</article>`).join('')}</div>`, ['Обращений нет', 'Если что-то сломалось или мешает — сообщите.', btn('Сообщить о проблеме', { href: '#/submit/issue', cls: 'btn-primary' })]) });
route('/me/favorites', { title: 'Избранное', area: 'me', need: RES, group: ME, render: () => pageHead('Избранное', { sub: 'Видно только вам. До 500 записей.' }) + tabs('fav', [['ads', 'Объявления'], ['orgs', 'Организации'], ['news', 'Новости']], 'ads') + st(() => panel('fav', 'ads', `<div class="ads" style="grid-template-columns:repeat(auto-fill,minmax(min(260px,100%),1fr))">${DATA.ads.slice(0, 3).map(adCard).join('')}</div>`, 'ads') + panel('fav', 'orgs', `<div class="panel">${DATA.orgs.slice(0, 2).map(orgRow).join('')}</div>`, 'ads') + panel('fav', 'news', DATA.news.slice(0, 2).map(newsItem).join(''), 'ads'), ['В избранном пусто', 'Нажмите ♡ на объявлении или организации, чтобы сохранить.']) });
function chat(open, id) {
  const c = DATA.convs.find((x) => x.id == id) || DATA.convs[0];
  return `<div class="chat ${open ? 'open' : ''}"><div class="conv-list" aria-label="Диалоги">${DATA.convs.map((x) => `<a class="conv" href="#/me/messages/${x.id}" ${open && x.id === c.id ? 'aria-current="true"' : ''}>${av(x.who[0], 'sky', 44)}<div style="min-width:0"><b>${x.who}</b><span>${x.about} · ${x.last}</span></div><div style="text-align:right"><span class="meta">${x.ago}</span>${x.unread ? `<br><span class="u">${x.unread}</span>` : ''}</div></a>`).join('')}</div>
  <section class="dialog" aria-label="Диалог">${open ? `<div class="dialog-h"><a class="icon-btn only-t" href="#/me/messages" aria-label="К списку диалогов">←</a>${av(c.who[0], 'sky', 40)}<div style="flex:1;min-width:0"><b>${c.who}</b><div class="meta">${c.about}</div></div>${btn('', { icon: 'flag', cls: 'btn-ghost btn-sm', attrs: 'aria-label="Пожаловаться" data-act="modal" data-id="report"' })}${btn('Заблокировать', { cls: 'btn-ghost btn-sm hide-m', attrs: 'data-act="modal" data-id="danger" data-title="Заблокировать собеседника?" data-text="Вы перестанете получать от него сообщения. Он не узнает о блокировке." data-word="БЛОК" data-btn="Заблокировать" data-ok="Демо: заблокирован"' })}</div>
  <div class="msgs"><div class="pollnote">Сообщения обновляются примерно раз в 15 секунд, мгновенной доставки нет</div><div class="bub">Здравствуйте! Велосипед ещё продаёте?<small>10:31</small></div><div class="bub me">Да, ещё актуально. Можно вечером.<small>10:42 · отправлено</small></div><div class="bub">Отлично, подойду к 19:00.<small>10:44</small></div></div>
  <form class="composer" data-form data-ok="Демо: сообщение отправлено"><button type="button" class="icon-btn" aria-label="Прикрепить фото" ${demo('Демо: до 3 фото, видят только участники')}>${ic('image')}</button><label class="sr" for="msg">Сообщение</label><input id="msg" placeholder="Сообщение…" required><button class="btn btn-primary">Отправить</button></form>` : emptyBox('Выберите диалог', 'Переписка начинается с кнопки «Написать автору» у объявления или поста.')}</section></div>`;
}
route('/me/messages', { title: 'Сообщения', area: 'me', need: RES, group: ME, render: () => pageHead('Сообщения') + st(() => chat(false), ['Сообщений пока нет', 'Напишите автору объявления или поста — диалог появится здесь.']) });
route('/me/messages/:id', { title: 'Диалог', area: 'me', need: RES, group: ME, navKey: '/me/messages', sample: '/me/messages/1', render: (p) => pageHead('Сообщения') + chat(true, p.id) });
route('/me/groups', { title: 'Мои группы', area: 'me', need: RES, group: ME, render: (p) => pageHead('Мои группы', { actions: btn('Создать группу', { cls: 'btn-primary', icon: 'plus', attrs: 'data-act="modal" data-id="newgroup"' }) }) + (p.q.get('new') ? '<div class="alert info">' + ic('people') + '<div>Нажмите «Создать группу».</div></div>' : '') + st(() => `<div class="panel">${DATA.groups.map((g, i) => `<div class="org">${av(g.letter, g.tone, 56)}<div><h3><a href="#/groups/${g.id}">${g.name}</a></h3><div class="meta">${['Владелец', 'Участник', 'Заявка на рассмотрении'][i]} · ${g.members} участников</div></div>${i === 0 ? btn('Управлять', { cls: 'btn-sm btn-secondary', attrs: demo('Демо: участники, заявки, модераторы группы') }) : badge(i === 2 ? 'Ожидает' : 'Участник', i === 2 ? 'warn' : '')}</div>`).join('')}</div>`, ['Вы пока не в группах', 'Найдите сообщество по интересам.', btn('Все группы', { href: '#/community?tab=groups' })]) });
MODALS.newgroup = () => `<h2>Новая группа</h2><form data-form data-ok="Демо: группа отправлена на проверку модератору SVETLY">${field('Название', { req: true })}${field('Описание', { type: 'textarea', rows: 3 })}${field('Тип', { type: 'select', opts: ['Открытая', 'Закрытая — вступление по заявке'] })}<p class="muted">Новая группа видна только вам, пока её не одобрит модератор.</p><div class="row-btns end">${btn('Отмена', { attrs: 'data-act="close"' })}${btn('Создать', { type: 'submit', cls: 'btn-primary' })}</div></form>`;
route('/me/notifications', { title: 'Уведомления', area: 'me', need: RES, group: ME, render: () => pageHead('Уведомления', { actions: btn('Прочитать все', { attrs: demo('Демо: всё прочитано') }) + btn('Настройки', { icon: 'settings', attrs: 'data-act="modal" data-id="notifset"' }) }) + tabs('nt', [['all', 'Все'], ['mod', 'Модерация'], ['com', 'Комментарии'], ['iss', 'Обращения'], ['grp', 'Группы']], 'all') + st(() => `<div class="tbl-wrap"><div class="mini" style="padding:0 16px">${DATA.notifs.map((n) => `<div class="r"><span>${n.unread ? '<b style="color:var(--primary)">●</b> ' : ''}<span class="badge">${n.cat}</span> ${n.text}</span><span class="meta">${n.ago}</span></div>`).join('')}</div></div><p class="meta">Email и push-уведомления не подключены — только в кабинете.</p>`, ['Уведомлений нет', 'Здесь появятся ответы, решения модераторов и статусы обращений.']) });
MODALS.notifset = () => `<h2>Настройки уведомлений</h2>${[['Комментарии и ответы', true, false], ['Группы', true, false], ['Модерация', true, true], ['Обращения', true, true], ['Системные', true, true]].map(([t, on, lock]) => `<div class="flag-row"><span>${t}${lock ? '<br><small class="meta">обязательные</small>' : ''}</span><span></span><button class="switch" aria-label="${t}" aria-pressed="${on}" ${lock ? 'disabled' : 'data-act="toggle"'}></button></div>`).join('')}<div class="row-btns end">${btn('Готово', { cls: 'btn-primary', attrs: 'data-act="close"' })}</div>`;
route('/me/reco', { title: 'Рекомендации', area: 'me', need: RES, group: ME, render: () => pageHead('Рекомендации', { sub: 'Учитываются только ваши интересы, свежесть и ближайшие события. История просмотров не используется.' }) + st(() => `<div class="lst">${[['Событие', DATA.events[2].title, 'ближайшее событие'], ['Организация', DATA.orgs[2].name, 'интерес «Детям и образование»'], ['Объявление', DATA.ads[0].title, 'интерес «Продам» · свежее']].map(([t, h, why]) => `<article class="card" style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><div style="flex:1;min-width:200px"><span class="badge">${t}</span><h3 style="margin:6px 0 2px">${h}</h3><span class="meta">Почему показано: ${why}</span></div>${btn('Скрыть', { cls: 'btn-sm btn-ghost', attrs: demo('Демо: скрыто. Вернуть можно ниже') })}</article>`).join('')}</div>`, ['Рекомендаций пока нет', 'Выберите интересы в профиле.', btn('Выбрать интересы', { href: '#/me/profile' })]) });
route('/me/profile', { title: 'Профиль и безопасность', area: 'me', need: RES, group: ME, render: () => pageHead('Профиль и безопасность') + tabs('pr', [['p', 'Профиль'], ['s', 'Безопасность'], ['i', 'Интересы']], 'p') +
  panel('pr', 'p', `<form class="form card" data-form data-ok="Демо: профиль сохранён">${field('Имя', { val: 'Житель (пример)', req: true })}${field('Email', { val: 'resident@example.test', type: 'email', req: true, help: 'Смена email — с подтверждением' })}${field('Район', { type: 'select', opts: ['Светлый', 'Октябрьский'] })}${btn('Сохранить', { type: 'submit', cls: 'btn-primary' })}</form>`, 'p') +
  panel('pr', 's', `<div class="lst"><form class="form card" data-form data-ok="Демо: пароль изменён">${field('Текущий пароль', { type: 'password', req: true })}${field('Новый пароль', { type: 'password', req: true, attrs: 'minlength="12"', help: 'От 12 символов' })}${btn('Сменить пароль', { type: 'submit', cls: 'btn-primary' })}</form><div class="card"><h3>Активные сессии</h3><div class="mini"><div class="r"><span><b>Этот браузер</b><br><span class="meta">Chrome · Новосибирск · сейчас</span></span>${badge('Текущая', 'ok')}</div><div class="r"><span>Телефон<br><span class="meta">Safari · 2 дня назад</span></span>${btn('Завершить', { cls: 'btn-sm btn-secondary', attrs: demo('Демо: сессия завершена') })}</div></div></div>
  <div class="card" style="border-color:var(--danger)"><h3>Удалить аккаунт</h3><p class="meta">Публикации будут сняты, сообщения — удалены у вас.</p>${btn('Удалить аккаунт', { cls: 'btn-danger', attrs: 'data-act="modal" data-id="danger" data-title="Удалить аккаунт?" data-text="Действие необратимо. Публикации будут сняты, вход станет невозможен." data-word="УДАЛИТЬ" data-btn="Удалить навсегда" data-ok="Демо: ничего не удалено"' })}${concept()}</div></div>`, 'p') +
  panel('pr', 'i', `<div class="card"><p class="meta">Интересы влияют только на рекомендации.</p><div class="chips">${DATA.cats.map((c, i) => `<button class="chip" data-act="toggle" aria-pressed="${i < 2}">${c}</button>`).join('')}</div></div>`, 'p') });

/* кабинет бизнеса */
const BIZ = ['business'];
route('/biz', { title: 'Кабинет бизнеса: обзор', area: 'biz', need: BIZ, group: BZ, render: () => pageHead('Мастер на час (пример)', { kicker: 'Кабинет бизнеса', actions: btn('Открыть карточку', { href: '#/org/2', icon: 'external' }) }) + `<div class="tiles">
<section class="tile w8"><div class="tile-h"><h2>Статус карточки</h2>${badge('Опубликована', 'ok')}</div><p>Изменения от 12 октября ${badge('На проверке', 'warn')} — до одобрения жители видят прежнюю версию.</p>${btn('Профиль организации', { href: '#/biz/profile', cls: 'btn-sm btn-secondary' })}</section>
<a class="tile kpi ink" href="#/biz/inquiries" style="text-decoration:none"><span>Новые заявки</span><b>1</b><span>«Нужно заменить смеситель…»</span></a>
<section class="tile"><div class="tile-h"><h2>Услуги</h2></div><div class="kpi"><b>3</b><span>в карточке</span></div>${btn('Управлять', { href: '#/biz/services', cls: 'btn-sm btn-secondary' })}</section>
<section class="tile"><div class="tile-h"><h2>Просмотры</h2>${concept()}</div><p class="meta">Статистики в продукте нет. Покажем только реальные агрегаты, когда появятся.</p></section>
<section class="tile"><div class="tile-h"><h2>Публикации</h2>${concept()}</div><p class="meta">Акции и новости от бизнеса — предлагаемая функция.</p></section></div>` });
route('/biz/profile', { title: 'Профиль организации', area: 'biz', need: BIZ, group: BZ, render: () => pageHead('Профиль организации', { sub: 'Каждое изменение опубликованной карточки проверяет администратор.' }) + `<div class="alert warn">${ic('clock')}<div><b>Изменения на проверке.</b> Отправлено 12 октября. Жители видят прежнюю версию.</div></div><div class="editor"><form class="form card" data-form data-ok="Демо: изменения отправлены на проверку">${field('Название', { val: 'Мастер на час (пример)', req: true })}${field('Категория', { type: 'select', opts: DATA.cats })}${field('Описание', { type: 'textarea', rows: 5, val: 'Мелкий бытовой ремонт по посёлку.' })}<div class="form-2">${field('Адрес', { val: 'выезд по посёлку' })}${field('Часы работы', { val: 'пн–сб 9–19' })}</div>${field('Телефон', { type: 'tel', val: '+7 ··· ··· ·· ··' })}<div class="upload">${ic('image')}Логотип и фото работ</div>${btn('Отправить на проверку', { type: 'submit', cls: 'btn-primary' })}</form>
<aside class="card"><h3>Как увидят жители</h3><div class="org" style="grid-template-columns:48px 1fr">${av('М', 'sky', 48)}<div><b>Мастер на час (пример)</b><div class="meta">Ремонт · выезд</div></div></div><p class="meta">Предпросмотр карточки в каталоге.</p></aside></div>` });
route('/biz/services', { title: 'Услуги и предложения', area: 'biz', need: BIZ, group: BZ, render: () => pageHead('Услуги и предложения', { actions: btn('Добавить услугу', { cls: 'btn-primary', icon: 'plus', attrs: 'data-act="modal" data-id="svc"' }) }) + st(() => `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Услуга</th><th>Цена</th><th>Статус</th><th></th></tr></thead><tbody>${[['Мелкий ремонт, 1 час', 'от 800 ₽', 'Опубликована', 'ok'], ['Сборка мебели', 'от 1 500 ₽', 'Опубликована', 'ok'], ['Замена смесителя', 'от 1 200 ₽', 'На проверке', 'warn']].map(([t, p, s, tn]) => `<tr><td><b>${t}</b></td><td data-l="Цена">${p}</td><td data-l="Статус">${badge(s, tn)}</td><td class="tact">${btn('Изменить', { cls: 'btn-sm btn-ghost', attrs: 'data-act="modal" data-id="svc"' })}</td></tr>`).join('')}</tbody></table></div>`, ['Услуг пока нет', 'Добавьте первую — жители увидят её в карточке.', btn('Добавить услугу', { cls: 'btn-primary', attrs: 'data-act="modal" data-id="svc"' })]) });
MODALS.svc = () => `<h2>Услуга</h2><form data-form data-ok="Демо: отправлено на проверку">${field('Название', { req: true })}${field('Цена', { ph: 'от 800 ₽' })}${field('Описание', { type: 'textarea', rows: 3 })}<div class="row-btns end">${btn('Отмена', { attrs: 'data-act="close"' })}${btn('Сохранить', { type: 'submit', cls: 'btn-primary' })}</div></form>`;
route('/biz/posts', { title: 'Публикации бизнеса', area: 'biz', need: BIZ, group: BZ, render: () => pageHead('Публикации', { actions: concept() }) + conceptNote('Публикаций от имени бизнеса (акции, новости) в продукте нет. Сейчас владелец может разместить вакансию или объявление от своего аккаунта.') + `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Публикация</th><th>Тип</th><th>Статус</th></tr></thead><tbody><tr><td>Скидка на сборку мебели (пример)</td><td data-l="Тип">Акция</td><td data-l="Статус">${badge('Черновик')}</td></tr><tr><td>Ищем помощника (пример)</td><td data-l="Тип">Вакансия</td><td data-l="Статус">${badge('Опубликовано', 'ok')}</td></tr></tbody></table></div>` });
route('/biz/inquiries', { title: 'Заявки жителей', area: 'biz', need: BIZ, group: BZ, render: () => pageHead('Заявки жителей', { sub: 'Сейчас в продукте заявки видны в кабинете жителя; здесь — предлагаемое место в кабинете бизнеса.' }) + tabs('inq', [['new', 'Новые'], ['all', 'Все']], 'new') + st(() => `<div class="lst">${DATA.inquiries.map((x) => `<a class="card" href="#/biz/inquiries/${x.id}" style="text-decoration:none;display:block"><div class="status-row">${badge(x.status, x.tone)}<span class="meta">${x.from} · ${x.ago}</span></div><p style="margin:8px 0 0">${x.text}</p></a>`).join('')}</div>`, ['Заявок пока нет', 'Когда житель оставит заявку в карточке, она появится здесь.']) });
route('/biz/inquiries/:id', { title: 'Заявка', area: 'biz', need: BIZ, group: BZ, navKey: '/biz/inquiries', sample: '/biz/inquiries/1', render: (p) => { const x = DATA.inquiries.find((i) => i.id == p.id) || DATA.inquiries[0]; return pageHead('Заявка № ' + x.id, { crumbs: [['Заявки', '#/biz/inquiries'], ['№ ' + x.id]] }) + `<div class="editor"><div class="card"><div class="status-row">${badge(x.status, x.tone)}<span class="meta">${x.from} · ${x.ago}</span></div><p style="font-size:18px">${x.text}</p><form class="form" data-form data-ok="Демо: ответ отправлен в «Сообщения» жителя">${field('Ответ', { type: 'textarea', req: true, rows: 4 })}<div class="row-btns">${btn('Ответить', { type: 'submit', cls: 'btn-primary' })}${btn('Закрыть заявку', { attrs: demo('Демо: заявка закрыта') })}</div></form></div><aside class="card"><h3>О заявке</h3><p class="meta">Контакты жителя не передаются — переписка внутри SVETLY.</p></aside></div>`; } });
route('/biz/stats', { title: 'Статистика', area: 'biz', need: BIZ, group: BZ, render: () => pageHead('Статистика', { actions: concept() }) + conceptNote('Статистики для бизнеса в продукте нет. Предложение: только агрегаты без персональных данных — просмотры карточки, клики «Позвонить»/«Сайт» как оценка (клик ≠ звонок), число заявок.') + `<div class="tiles"><div class="tile"><div class="kpi"><span>Просмотры карточки, 30 дней</span><b>—</b><span>данных нет</span></div></div><div class="tile"><div class="kpi"><span>Клики «Позвонить»</span><b>—</b><span>оценка, не звонки</span></div></div><div class="tile"><div class="kpi"><span>Заявки</span><b>3</b><span>пример</span></div></div><div class="tile w12"><h2>Динамика (макет)</h2><div class="bars" aria-hidden="true">${[30, 45, 20, 60, 50, 70, 40, 55, 65, 35, 50, 45].map((v) => `<i style="height:${v}%"></i>`).join('')}</div><p class="meta">Пример визуализации. Реальных данных нет.</p></div></div>` });
route('/biz/settings', { title: 'Настройки и проверка', area: 'biz', need: BIZ, group: BZ, render: () => pageHead('Настройки и проверка') + `<div class="lst"><div class="card"><h3>История проверки</h3><div class="mini"><div class="r"><span>Карточка одобрена</span><span class="meta">3 марта</span></div><div class="r"><span>Изменения отклонены: «укажите часы работы»</span><span class="meta">20 мая</span></div><div class="r"><span>Изменения на проверке</span>${badge('Ожидает', 'warn')}</div></div></div><div class="card"><h3>Сотрудники</h3>${concept()}<p class="meta">Доступ к кабинету для сотрудников компании — предлагаемая функция.</p></div><div class="card"><h3>Снять карточку с публикации</h3>${btn('Снять с публикации', { cls: 'btn-danger', attrs: 'data-act="modal" data-id="danger" data-title="Снять карточку?" data-text="Карточка пропадёт из каталога и поиска. Вернуть — через повторную проверку." data-word="СНЯТЬ" data-btn="Снять" data-ok="Демо: ничего не изменено"' })}</div></div>` });
